import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that allows for space-efficient membership testing.
    Uses straightforward hashing and bit array techniques to manage a probabilistic data structure.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal size of the bit array and number of hash functions
        self.size = self._calculate_bit_array_size()
        self.num_hashes = self._calculate_num_hash_functions()

        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array based on expected items and false positive rate."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hash_functions(self) -> int:
        """Calculate the optimal number of hash functions based on the bit array size and expected items."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Hash the item using SHA-256 and a seed for varying hash outputs."""
        hash_result = hashlib.sha256(f"{item}{seed}".encode()).hexdigest()
        return int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            if self.bit_array[index] == 0:
                return False
        return True

import hashlib
