class BloomFilter:
    """
    A Bloom Filter is a space-efficient probabilistic data structure used to test 
    whether an element is a member of a set. False positives are possible, but false 
    negatives are not. This implementation uses a bit array for storage and multiple 
    hash functions for adding and checking membership of items.

    The size of the bit array and the number of hash functions are calculated based 
    on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()
        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((-self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions needed."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate hash values based on the item and the configured hash count."""
        hash_values = []
        for i in range(self.hash_count):
            hash_value = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            hash_index = int(hash_value, 16) % self.size
            hash_values.append(hash_index)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._hashes(item))

import hashlib
import math

class BloomFilter:
    """
    Implementation of a Bloom Filter which allows for adding items and checking for membership.

    This implementation computes the optimal bit array size and number of hash functions based on
    the expected number of items and the desired false positive rate. The hash functions are
    implemented using a simple hash-based approach, ensuring that the Bloom Filter can efficiently
    manage memory and perform lookups.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        """
        Initialize the Bloom Filter with expected items and desired false positive rate.

        :param expected_items: The number of items the filter is expected to handle.
        :param false_positive_rate: The desired rate of false positives.
        """
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal parameters
        self.size = self.calculate_size(expected_items, false_positive_rate)
        self.num_hashes = self.calculate_num_hashes(self.size, expected_items)

        # Initialize bit array
        self.bit_array = [0] * self.size

    @staticmethod
    def calculate_size(expected_items: int, false_positive_rate: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-expected_items * math.log(false_positive_rate) / (math.log(2) ** 2))

    @staticmethod
    def calculate_num_hashes(size: int, expected_items: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((size / expected_items) * math.log(2)))

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_value = self.hash(item, i) % self.size
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for i in range(self.num_hashes):
            hash_value = self.hash(item, i) % self.size
            if self.bit_array[hash_value] == 0:
                return False
        return True

    def hash(self, item: str, seed: int) -> int:
        """Generate a hash for an item using SHA-256 and seed."""
        return int(hashlib.sha256((item + str(seed)).encode('utf-8')).hexdigest(), 16)
